'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Int8Array = require( '@stdlib/array/int8' );
var Uint8Array = require( '@stdlib/array/uint8' );
var Uint8ClampedArray = require( '@stdlib/array/uint8c' );
var Int16Array = require( '@stdlib/array/int16' );
var Uint16Array = require( '@stdlib/array/uint16' );
var Int32Array = require( '@stdlib/array/int32' );
var Uint32Array = require( '@stdlib/array/uint32' );
var Float32Array = require( '@stdlib/array/float32' );
var Float64Array = require( '@stdlib/array/float64' );
var isArray = require( '@stdlib/assert/is-array' );
var pkg = require( './../package.json' ).name;
var copyWithin = require( './../lib' );


// MAIN //

bench( pkg+'::array', function benchmark( b ) {
	var arr;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		arr = [ i, i+1, i+2, i+3, i+4, i+5, i+6, i+7, i+8, i+9 ];
		arr = copyWithin( arr, 0, 5 );
		if ( !isArray( arr ) ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( !isArray( arr ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::array_with_built_in', function benchmark( b ) {
	var arr;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		arr = [ i, i+1, i+2, i+3, i+4, i+5, i+6, i+7, i+8, i+9 ];
		arr = arr.copyWithin( 0, 5 );
		if ( !isArray( arr ) ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( !isArray( arr ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::array_like_object', function benchmark( b ) {
	var arr;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		arr = {
			'0': i,
			'1': i+1,
			'2': i+2,
			'3': i+3,
			'4': i+4,
			'5': i+5,
			'6': i+6,
			'7': i+7,
			'8': i+8,
			'9': i+9,
			'length': 10
		};
		arr = copyWithin( arr, 0, 5 );
		if ( typeof arr !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( typeof arr !== 'object' ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::int8array', function benchmark( b ) {
	var arr;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		arr = new Int8Array( [ i, i+1, i+2, i+3, i+4, i+5, i+6, i+7, i+8, i+9 ] ); // eslint-disable-line max-len
		arr = copyWithin( arr, 0, 5 );
		if ( !(arr instanceof Int8Array) ) {
			b.fail( 'should return an Int8Array' );
		}
	}
	b.toc();
	if ( !(arr instanceof Int8Array) ) {
		b.fail( 'should return an Int8Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

